import{_ as s,I as o,o as g,c as h,b6 as r,J as e}from"./chunks/framework.COUcLbTA.js";const G=JSON.parse('{"title":"RAG：检索增强生成","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/8-artificial-intelligence/rag.md","filePath":"zh-cn/appendix/8-artificial-intelligence/rag.md"}'),p={name:"zh-cn/appendix/8-artificial-intelligence/rag.md"};function _(c,t,A,u,R,b){const a=o("RAGPipelineDemo"),n=o("ChunkingStrategyDemo"),d=o("RetrievalDemo"),i=o("RAGArchitectureDemo"),l=o("RAGvsFineTuningDemo");return g(),h("div",null,[t[0]||(t[0]=r('<h1 id="rag-检索增强生成" tabindex="-1">RAG：检索增强生成 <a class="header-anchor" href="#rag-检索增强生成" aria-label="Permalink to “RAG：检索增强生成”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>为什么 ChatGPT 有时候会&quot;一本正经地胡说八道&quot;？</strong> 大语言模型的知识来自训练数据，但训练数据有截止日期，也不包含你公司的内部文档。RAG（Retrieval-Augmented Generation，检索增强生成）就是解决这个问题的核心技术——让 AI 在回答之前，先去&quot;查资料&quot;。</p></div><p><strong>这篇文章会带你学什么？</strong></p><p>学完这章后，你将获得：</p><ul><li><strong>核心概念理解</strong>：明白 RAG 是什么、为什么需要它，以及它如何解决大模型的&quot;幻觉&quot;问题</li><li><strong>完整流程认知</strong>：掌握从文档加载、分块、向量化到检索、生成的端到端流程</li><li><strong>技术选型能力</strong>：了解不同分块策略、检索方法的优劣，能根据场景做出选择</li><li><strong>架构演进视角</strong>：理解 RAG 从 Naive 到 Advanced 再到 Modular 的演进路线</li><li><strong>实践决策能力</strong>：知道什么时候该用 RAG、什么时候该用微调</li></ul><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>RAG 基础流程</td><td>索引、检索、生成三阶段</td></tr><tr><td><strong>第 2 章</strong></td><td>文本分块策略</td><td>固定分块、语义分块、递归分块</td></tr><tr><td><strong>第 3 章</strong></td><td>检索技术</td><td>向量检索、关键词检索、混合检索</td></tr><tr><td><strong>第 4 章</strong></td><td>架构演进</td><td>Naive RAG → Advanced RAG → Modular RAG</td></tr><tr><td><strong>第 5 章</strong></td><td>RAG vs 微调</td><td>两种方案的适用场景对比</td></tr></tbody></table><hr><h2 id="_0-全景图-为什么大模型需要-查资料" tabindex="-1">0. 全景图：为什么大模型需要&quot;查资料&quot;？ <a class="header-anchor" href="#_0-全景图-为什么大模型需要-查资料" aria-label="Permalink to “0. 全景图：为什么大模型需要&quot;查资料&quot;？”">​</a></h2><p>想象你是一个博学的教授，读过无数书籍。但如果有人问你&quot;昨天公司的销售数据是多少&quot;，你肯定答不上来——因为这些信息不在你读过的书里。</p><p>大语言模型面临的就是同样的困境：</p><ul><li><strong>知识有截止日期</strong>：GPT-4 的训练数据截止到某个时间点，之后发生的事它不知道</li><li><strong>缺乏私有知识</strong>：你公司的内部文档、产品手册、客户数据，模型从未见过</li><li><strong>容易产生幻觉</strong>：当模型不确定答案时，它倾向于&quot;编造&quot;一个看起来合理的回答</li></ul><div class="tip custom-block"><p class="custom-block-title">RAG 的核心思想</p><p>RAG 的解决方案非常直觉：<strong>在让模型回答之前，先帮它找到相关的参考资料</strong>。就像开卷考试——你不需要记住所有知识，只需要知道去哪里找、怎么找。</p><p>RAG = 检索（Retrieval）+ 增强（Augmented）+ 生成（Generation）</p></div><hr><h2 id="_1-rag-基础流程-索引、检索、生成" tabindex="-1">1. RAG 基础流程：索引、检索、生成 <a class="header-anchor" href="#_1-rag-基础流程-索引、检索、生成" aria-label="Permalink to “1. RAG 基础流程：索引、检索、生成”">​</a></h2><p>RAG 的工作流程可以分为两个阶段：<strong>离线索引</strong>和<strong>在线查询</strong>。</p><p>离线阶段就像图书馆的编目工作——把所有书籍分类、编号、上架，方便日后查找。在线阶段则是读者来图书馆查资料的过程——根据问题找到相关书籍，然后综合信息给出回答。</p>',16)),e(a),t[1]||(t[1]=r('<div class="tip custom-block"><p class="custom-block-title">三个核心阶段</p><ol><li><strong>索引阶段（Indexing）</strong>：将原始文档加载、清洗、分块，然后通过嵌入模型转化为向量，存入向量数据库。这是一次性的准备工作。</li><li><strong>检索阶段（Retrieval）</strong>：用户提问时，将问题也转化为向量，在向量数据库中搜索最相似的文档片段。</li><li><strong>生成阶段（Generation）</strong>：将检索到的文档片段和用户问题一起拼接为 Prompt，交给大模型生成最终回答。</li></ol></div><table tabindex="0"><thead><tr><th>阶段</th><th>输入</th><th>输出</th><th>关键技术</th></tr></thead><tbody><tr><td>索引</td><td>原始文档</td><td>向量数据库</td><td>文本分块、嵌入模型</td></tr><tr><td>检索</td><td>用户问题</td><td>Top-K 文档片段</td><td>向量相似度、重排序</td></tr><tr><td>生成</td><td>问题 + 上下文</td><td>最终回答</td><td>Prompt 工程、LLM</td></tr></tbody></table><hr><h2 id="_2-文本分块-把大象装进冰箱" tabindex="-1">2. 文本分块：把大象装进冰箱 <a class="header-anchor" href="#_2-文本分块-把大象装进冰箱" aria-label="Permalink to “2. 文本分块：把大象装进冰箱”">​</a></h2><p>文本分块是 RAG 中最容易被忽视、却对效果影响最大的环节。为什么需要分块？因为大模型的上下文窗口有限，我们不可能把整本书塞进去。更重要的是，<strong>分块的质量直接决定了检索的质量</strong>。</p><p>想象你在图书馆找一本书的某个知识点。如果整本书是一个&quot;块&quot;，检索到了也没用——你还是得翻遍全书。但如果按章节甚至段落分块，就能精准定位到你需要的内容。</p>',6)),e(n),t[2]||(t[2]=r('<div class="tip custom-block"><p class="custom-block-title">分块策略的选择</p><ul><li><strong>固定大小分块</strong>：按字符数或 token 数切分，简单粗暴但可能切断语义</li><li><strong>递归分块</strong>：先按段落分，段落太长再按句子分，保持语义完整性</li><li><strong>语义分块</strong>：用嵌入模型判断语义边界，相似度突变处切分</li><li><strong>文档结构分块</strong>：利用 Markdown 标题、HTML 标签等结构信息分块</li></ul><p>没有&quot;最好&quot;的分块策略，只有最适合你数据的策略。一般建议从递归分块开始，chunk 大小 200-500 tokens，overlap 10-20%。</p></div><hr><h2 id="_3-检索技术-如何找到最相关的内容" tabindex="-1">3. 检索技术：如何找到最相关的内容？ <a class="header-anchor" href="#_3-检索技术-如何找到最相关的内容" aria-label="Permalink to “3. 检索技术：如何找到最相关的内容？”">​</a></h2><p>分块完成后，下一个关键问题是：<strong>用户提了一个问题，怎么从成千上万个文档片段中找到最相关的那几个？</strong></p><p>这就像在一个巨大的图书馆里找书。你可以按书名关键词搜索（关键词检索），也可以描述你想要的内容让图书管理员帮你找（语义检索），最好的方式是两者结合（混合检索）。</p>',5)),e(d),t[3]||(t[3]=r('<table tabindex="0"><thead><tr><th>检索方式</th><th>原理</th><th>优势</th><th>劣势</th></tr></thead><tbody><tr><td>关键词检索（BM25）</td><td>基于词频和逆文档频率</td><td>精确匹配、速度快</td><td>无法理解语义、同义词失效</td></tr><tr><td>向量检索</td><td>基于嵌入向量的余弦相似度</td><td>理解语义、支持模糊匹配</td><td>对专有名词不敏感</td></tr><tr><td>混合检索</td><td>融合关键词和向量检索结果</td><td>兼顾精确和语义</td><td>需要调权重、复杂度高</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">重排序（Reranking）</p><p>检索到候选文档后，通常还需要一步&quot;重排序&quot;。初始检索追求召回率（尽量不遗漏），重排序追求精确率（把最相关的排到最前面）。常用的重排序模型有 Cohere Rerank、BGE Reranker 等，它们使用交叉编码器对 query-document 对进行精细打分。</p></div><hr><h2 id="_4-架构演进-从简单到智能" tabindex="-1">4. 架构演进：从简单到智能 <a class="header-anchor" href="#_4-架构演进-从简单到智能" aria-label="Permalink to “4. 架构演进：从简单到智能”">​</a></h2><p>RAG 技术在短短两年内经历了三代演进，每一代都在解决上一代的痛点。</p>',5)),e(i),t[4]||(t[4]=r('<div class="tip custom-block"><p class="custom-block-title">三代 RAG 架构对比</p><ul><li><strong>Naive RAG（2023）</strong>：最基础的&quot;索引→检索→生成&quot;流程，实现简单但效果有限。问题包括：检索质量不稳定、无法处理复杂查询、容易引入噪音上下文。</li><li><strong>Advanced RAG（2024）</strong>：在 Naive RAG 基础上增加了查询改写、混合检索、重排序、上下文压缩等优化环节，显著提升了检索精度和生成质量。</li><li><strong>Modular RAG（2025）</strong>：将 RAG 拆解为可插拔的模块，支持路由判断、自适应检索、自我反思等高级能力。可根据查询类型动态选择最优处理流程。</li></ul></div><hr><h2 id="_5-rag-vs-微调-该选哪个" tabindex="-1">5. RAG vs 微调：该选哪个？ <a class="header-anchor" href="#_5-rag-vs-微调-该选哪个" aria-label="Permalink to “5. RAG vs 微调：该选哪个？”">​</a></h2><p>当你想让大模型掌握特定领域的知识时，通常有两条路：RAG 和微调（Fine-tuning）。它们不是互斥的，而是互补的。</p><p>打个比方：<strong>微调像是让学生上培训班</strong>，把知识内化到大脑里；<strong>RAG 像是给学生发参考书</strong>，考试时可以翻阅。两种方式各有优劣，关键看你的具体需求。</p>',5)),e(l),t[5]||(t[5]=r('<table tabindex="0"><thead><tr><th>维度</th><th>RAG</th><th>微调</th></tr></thead><tbody><tr><td>知识更新</td><td>实时更新，改文档即可</td><td>需要重新训练</td></tr><tr><td>成本</td><td>低（无需 GPU 训练）</td><td>高（需要训练资源）</td></tr><tr><td>可解释性</td><td>高（可追溯来源）</td><td>低（知识内化在权重中）</td></tr><tr><td>适用场景</td><td>知识库问答、文档检索</td><td>风格迁移、特定任务优化</td></tr><tr><td>幻觉控制</td><td>较好（有参考依据）</td><td>一般（仍可能幻觉）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">实践建议</p><p>大多数场景下，<strong>先试 RAG</strong>。RAG 的优势在于：不需要训练、知识可实时更新、回答可追溯来源。只有当你需要改变模型的&quot;行为模式&quot;（比如输出格式、语言风格、推理方式）时，才考虑微调。最强的方案往往是 <strong>RAG + 微调</strong> 的组合。</p></div><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>RAG 是当前让大模型&quot;落地&quot;最实用的技术之一。它的核心价值在于：让模型的回答有据可查、知识可实时更新、幻觉可有效控制。</p><p>回顾本章的关键要点：</p><ol><li><strong>RAG 解决的核心问题</strong>：大模型知识过时、缺乏私有数据、容易幻觉</li><li><strong>三阶段流程</strong>：索引（离线准备）→ 检索（在线查找）→ 生成（综合回答）</li><li><strong>分块是基础</strong>：分块质量直接决定检索质量，选择合适的分块策略至关重要</li><li><strong>检索是关键</strong>：混合检索 + 重排序是目前效果最好的组合</li><li><strong>架构在演进</strong>：从 Naive RAG 到 Modular RAG，系统越来越智能和灵活</li><li><strong>RAG 和微调互补</strong>：大多数场景先试 RAG，需要改变模型行为时再考虑微调</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><a href="https://python.langchain.com/docs/tutorials/rag/" target="_blank" rel="noreferrer">LangChain RAG 教程</a> - 最流行的 RAG 框架实战指南</li><li><a href="https://docs.llamaindex.ai/" target="_blank" rel="noreferrer">LlamaIndex 文档</a> - 专注于 RAG 的框架，提供丰富的数据连接器</li><li><a href="https://arxiv.org/abs/2312.10997" target="_blank" rel="noreferrer">RAG Survey 论文</a> - 全面的 RAG 技术综述</li><li><a href="https://www.pinecone.io/learn/chunking-strategies/" target="_blank" rel="noreferrer">Chunking Strategies</a> - Pinecone 的分块策略详解</li><li><a href="https://superlinked.com/vector-db-comparison" target="_blank" rel="noreferrer">向量数据库对比</a> - 主流向量数据库的功能对比</li></ul>',9))])}const k=s(p,[["render",_]]);export{G as __pageData,k as default};
